<template><div class="rounded bg-white p-6 shadow"><h1 class="mb-6 text-2xl font-bold">글 수정</h1><BoardForm v-if="form" :model="form" submit-text="수정" @submit="submit"/></div></template>
<script setup>import{onMounted,reactive}from'vue';import{useRoute,useRouter}from'vue-router';import{boardApi}from'../api/boardApi';import BoardForm from'../components/BoardForm.vue';const route=useRoute(),router=useRouter(),form=reactive({title:'',content:''});onMounted(async()=>Object.assign(form,(await boardApi.get(route.params.id)).data));async function submit(){await boardApi.update(route.params.id,form);router.push(`/boards/${route.params.id}`)}</script>